package zw.ac.msu.dzimbahub.controller;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.security.core.Authentication;import org.springframework.web.server.ResponseStatusException;import zw.ac.msu.dzimbahub.auth.*;import zw.ac.msu.dzimbahub.model.*;import zw.ac.msu.dzimbahub.repository.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class OperationsControllerTest {@Mock UserActionRepository actions;@Mock PropertyRepository properties;@Mock AppUserRepository users;@Mock Authentication authentication;
 @Test void landlordCannotSendTenantEnquiry(){when(authentication.getName()).thenReturn("landlord@example.com");when(users.findByEmailIgnoreCase("landlord@example.com")).thenReturn(Optional.of(new AppUser("Landlord","landlord@example.com","hash",UserRole.LANDLORD)));OperationsController controller=new OperationsController(actions,properties,users);var error=assertThrows(ResponseStatusException.class,()->controller.message(new OperationsController.ActionRequest(1L,"Hello",null,null,null,null),authentication));assertEquals(403,error.getStatusCode().value());verify(properties,never()).findById(anyLong());}
 @Test void tenantCannotReadLandlordActionInbox(){when(authentication.getName()).thenReturn("tenant@example.com");when(users.findByEmailIgnoreCase("tenant@example.com")).thenReturn(Optional.of(new AppUser("Tenant","tenant@example.com","hash",UserRole.TENANT)));OperationsController controller=new OperationsController(actions,properties,users);var error=assertThrows(ResponseStatusException.class,()->controller.landlordActions(authentication));assertEquals(403,error.getStatusCode().value());verify(actions,never()).findByLandlordEmailOrderByCreatedAtDesc(anyString());}
}
